    retentionScore: 81,
    hookIdea: 'Nunca mais erre o ponto do hambúrguer artesanal.'
  }
];

try {
  const rawResp = $input.first().json.response;
  if (rawResp) {
    const parsed = typeof rawResp === 'string' ? JSON.parse(rawResp) : rawResp;
    if (parsed.trends && Array.isArray(parsed.trends) && parsed.trends.length > 0) {
      return [{ json: { success: true, source: 'ollama', trends: parsed.trends } }];
    }
  }
} catch (e) {}

return [{ json: { success: true, source: 'fallback_resilience', trends: fallbackTrends } }];
